-- Getting there: where an instance is entered outside and how to reach it, from the bundled travel facts
-- (Data/TravelData.lua, generated by tools/gen_travel.lua; docs/DATA-SOURCES.md) and the client's maps.
--
--   Travel.For(planOrEntry)    -> the instance's record { key, e, zone, zm, sub, fac, how, stone, hint, iid, maps }
--                                 or nil (key: the instance key, Providers.Key of its name)
--   Travel.Here(instanceID, uiMapID?) -> the records of the instance the player is in, by its map ID (not its name,
--                                 which is localized); a wing of a shared instance by its floor map when given
--   Travel.Entrance(rec)       -> { uiMapID?, x?, y? (0..1 on the zone's map), continent?, wx?, wy? (world yards),
--                                 learned? }: the entrance the player has used (global.entrances, Model/TravelLive.lua)
--                                 when there is one, else the bundled one (Travel.Bundled)
--   Travel.ZoneName(rec), Travel.StoneZone(stone) -> the zone's name in the player's language (its map's name)
--   Travel.Where(rec, uiMapID?) -> that zone (or the given map's name) and the area, unless the area reads the same
--   Travel.ContinentName(uiMapID) -> the continent above a map (its parents), in the player's language
--   Travel.Player()            -> { uiMapID, x, y, continent?, wx?, wy? } outdoors; nil inside instances (the client
--                                 gives no position there: docs/COMPATIBILITY.md section 10)
--   Travel.Nearest(rec, faction, n) -> the faction's nearest flight masters to the entrance (Prep.NearestNodes)
--   Travel.ToMap(continent, wx, wy, uiMapID?) -> uiMapID, x, y on a map
-- Every client call is guarded; values read from the game pass Util.Plain.

local _, ns = ...
local Travel = ns:NewModule("Travel")
local Util = ns.Util

local index -- [instance key] = record
local resolved, bundled = {}, {} -- [record] = entrance, per session (with a learned one; the bundled one)

local function data()
	return rawget(ns, "TravelData") or { instances = {}, nodes = {}, transports = {} }
end

function Travel.Reset()
	index, resolved, bundled = nil, {}, {}
end

local function buildIndex()
	if not index then
		index = {}
		for name, rec in pairs(data().instances or {}) do
			local k = ns.Providers.Key(name)
			if k then
				index[k] = rec
				rec.key = k
			end
		end
	end
	return index
end

function Travel.Nodes()
	return data().nodes or {}
end

function Travel.Transports()
	return data().transports or {}
end

-- A plan ({ instance = { name } }) or a home entry ({ name }).
function Travel.For(target)
	if type(target) ~= "table" then
		return nil
	end
	local name = type(target.instance) == "table" and target.instance.name or target.name
	local k = ns.Providers.Key(name)
	return k and buildIndex()[k] or nil
end

local function has(list, x)
	for _, v in ipairs(list or {}) do
		if v == x then
			return true
		end
	end
	return false
end

-- The records of the instance the player is in: those with its instance map ID; when several share it (the wings of
-- Scarlet Monastery, Dire Maul, Stratholme, Blackrock Spire) and the client gives a map, the ones whose floors hold it.
-- Sorted by key, so the answer does not depend on table order.
function Travel.Here(instanceID, uiMapID)
	local out = {}
	if not Util.IsInteger(instanceID) then
		return out
	end
	for _, rec in pairs(buildIndex()) do
		if rec.iid == instanceID then
			out[#out + 1] = rec
		end
	end
	if #out > 1 and Util.IsInteger(uiMapID) then
		local narrowed = {}
		for _, rec in ipairs(out) do
			if has(rec.maps, uiMapID) then
				narrowed[#narrowed + 1] = rec
			end
		end
		if #narrowed > 0 then
			out = narrowed
		end
	end
	table.sort(out, function(a, b)
		return a.key < b.key
	end)
	return out
end

local function xy(v)
	if type(v) ~= "table" then
		return nil
	end
	local x, y
	if type(v.GetXY) == "function" then
		local ok, a, b = pcall(v.GetXY, v)
		if ok then
			x, y = a, b
		end
	end
	if x == nil then
		x, y = v.x, v.y
	end
	x, y = Util.Plain(x), Util.Plain(y)
	if Util.IsFiniteNumber(x) and Util.IsFiniteNumber(y) then
		return x, y
	end
	return nil
end

local function vector(x, y)
	if type(CreateVector2D) == "function" then
		local ok, v = pcall(CreateVector2D, x, y)
		if ok and v then
			return v
		end
	end
	return { x = x, y = y }
end

-- World yards on a continent -> a spot on a map: the client's best map for the spot, or the given one.
function Travel.ToMap(continent, wx, wy, uiMapID)
	if not (C_Map and C_Map.GetMapPosFromWorldPos) then
		return nil
	end
	local ok, map, pos = pcall(C_Map.GetMapPosFromWorldPos, continent, vector(wx, wy), uiMapID)
	map = ok and Util.Plain(map) or nil
	local x, y = xy(pos)
	if Util.IsInteger(map) and x then
		return map, x, y
	end
	return nil
end

-- A spot on a map -> continent, world yards.
function Travel.ToWorld(uiMapID, x, y)
	if not (C_Map and C_Map.GetWorldPosFromMapPos and Util.IsInteger(uiMapID)) then
		return nil
	end
	local ok, continent, world = pcall(C_Map.GetWorldPosFromMapPos, uiMapID, vector(x, y))
	continent = ok and Util.Plain(continent) or nil
	local wx, wy = xy(world)
	if Util.IsInteger(continent) and wx then
		return continent, wx, wy
	end
	return nil
end

-- The zone's name in the player's language (its map's name: rec.zm, which the generator requires), else the bundled
-- English one.
function Travel.ZoneName(rec)
	if type(rec) ~= "table" then
		return nil
	end
	return ns.Instances.MapName(rec.zm) or rec.zone
end

-- The zone shown (the given map's name, else the zone's) with the area the entrance lies in, unless that area reads
-- the same as the zone shown: "Burning Steppes  •  Blackrock Mountain".
function Travel.Where(rec, uiMapID)
	if type(rec) ~= "table" then
		return nil
	end
	local zone = (uiMapID and ns.Instances.MapName(uiMapID)) or Travel.ZoneName(rec)
	if rec.sub and (not zone or rec.sub:lower() ~= zone:lower()) then
		return zone and (zone .. "  •  " .. rec.sub) or rec.sub
	end
	return zone
end

-- A summoning stone's zone in the player's language, else the bundled English name.
function Travel.StoneZone(stone)
	return (Util.IsInteger(stone.map) and ns.Instances.MapName(stone.map)) or stone.zone
end

local function inside01(x, y)
	return x and x >= 0 and x <= 1 and y >= 0 and y <= 1
end

-- The record's zone map (the bundled uiMapID).
function Travel.ZoneMap(rec)
	return rec.zm
end

-- A spot { map, x, y } or { c, x, y } on its zone's map and in the world, as far as the client can say.
local function place(rec, e)
	local out = {}
	if e.map then
		out.uiMapID, out.x, out.y = e.map, e.x, e.y
		out.continent, out.wx, out.wy = Travel.ToWorld(e.map, e.x, e.y)
	else
		out.continent, out.wx, out.wy = e.c, e.x, e.y
		-- The researched zone's map first (the client's "best" map may be a city or a continent), else the best map.
		local zone = rec.zm
		local map, x, y
		if zone then
			map, x, y = Travel.ToMap(e.c, e.x, e.y, zone)
			if not inside01(x, y) then
				map = nil
			end
		end
		if not map then
			map, x, y = Travel.ToMap(e.c, e.x, e.y)
			if not inside01(x, y) then
				map, x, y = nil, nil, nil
			end
		end
		out.uiMapID, out.x, out.y = map, x, y
	end
	return out
end

-- The bundled entrance (Data/TravelData.lua); nil when the research has none. Cached per session.
function Travel.Bundled(rec)
	if type(rec) ~= "table" or type(rec.e) ~= "table" then
		return nil
	end
	local hit = bundled[rec]
	if not hit then
		hit = place(rec, rec.e)
		bundled[rec] = hit
	end
	return hit
end

-- The entrance to use: the one the player has used (Model/TravelLive.lua Learn, on the record's zone map) once there
-- is one, else the bundled one. Cached per session (Travel.Reset after learning).
function Travel.Entrance(rec)
	if type(rec) ~= "table" then
		return nil
	end
	local hit = resolved[rec]
	if hit then
		return hit
	end
	local learned = rec.key and ns.db and ns.db.entrances and ns.db.entrances[rec.key]
	if learned then
		hit = place(rec, { map = learned.map, x = learned.x, y = learned.y })
		hit.learned = true
	else
		hit = Travel.Bundled(rec)
	end
	resolved[rec] = hit
	return hit
end

-- Where the player is outdoors; nil inside an instance or when the client gives no position.
function Travel.Player()
	if not (C_Map and C_Map.GetBestMapForUnit and C_Map.GetPlayerMapPosition) then
		return nil
	end
	local ok, map = pcall(C_Map.GetBestMapForUnit, "player")
	map = ok and Util.Plain(map) or nil
	if not Util.IsInteger(map) then
		return nil
	end
	local ok2, pos = pcall(C_Map.GetPlayerMapPosition, map, "player")
	local x, y
	if ok2 then
		x, y = xy(pos)
	end
	if not x or (x == 0 and y == 0) then
		return nil
	end
	local out = { uiMapID = map, x = x, y = y }
	out.continent, out.wx, out.wy = Travel.ToWorld(map, x, y)
	if type(GetPlayerFacing) == "function" then
		local okF, facing = pcall(GetPlayerFacing)
		facing = okF and Util.Plain(facing) or nil
		out.facing = Util.IsFiniteNumber(facing) and facing or nil
	end
	return out
end

-- The player's distance and direction to the entrance: yards, direction key, or nil plus a reason: "inside" (no
-- position), "continent" (another continent), "unknown" (the client cannot place one of them).
function Travel.Distance(ent, player)
	player = player or Travel.Player()
	if not player then
		return nil, "inside"
	end
	if not (ent and ent.wx and player.wx) then
		return nil, "unknown"
	end
	if player.continent ~= ent.continent then
		return nil, "continent"
	end
	return ns.Prep.WorldBearing(player.wx, player.wy, ent.wx, ent.wy)
end

function Travel.Nearest(rec, faction, n)
	local ent = Travel.Entrance(rec)
	if not (ent and ent.wx) then
		return {}
	end
	return ns.Prep.NearestNodes(Travel.Nodes(), ent.continent, ent.wx, ent.wy, faction, n)
end

-- A flight master's spot on a map (for a waypoint chain): the client's best map, or the given one. Nil when the
-- client cannot place it there.
function Travel.NodeOnMap(nodeID, uiMapID)
	for _, node in ipairs(Travel.Nodes()) do
		if node[1] == nodeID then
			local map, x, y = Travel.ToMap(node[3], node[4], node[5], uiMapID)
			if map and inside01(x, y) then
				return map, x, y
			end
			return nil
		end
	end
	return nil
end

-- The name of the continent a map lies on: up the map's parents (C_Map.GetMapInfo) to the first continent map.
local CONTINENT_TYPE = 2 -- Enum.UIMapType.Continent
function Travel.ContinentName(uiMapID)
	if not (C_Map and C_Map.GetMapInfo) then
		return nil
	end
	local want = (Enum and Enum.UIMapType and Enum.UIMapType.Continent) or CONTINENT_TYPE
	local map = uiMapID
	for _ = 1, 8 do -- a zone is two or three steps below its continent
		if not Util.IsInteger(map) or map <= 0 then
			return nil
		end
		local ok, info = pcall(C_Map.GetMapInfo, map)
		if not (ok and type(info) == "table") then
			return nil
		end
		if Util.Plain(info.mapType) == want then
			local name = Util.Plain(info.name)
			return type(name) == "string" and name ~= "" and name or nil
		end
		map = Util.Plain(info.parentMapID)
	end
	return nil
end
